SELECT  
    WHERE a.ASGN_STAT_CD='ACT' AND a.INPUT_BGN_DT <= make_date(#{year},12,31) AND a.INPUT_END_DT >= make_date(#{year},1,1)
    AND a.PROJ_ID=#{projectId}
    AND a.JOB_CD=#{jobCode}
    AND strpos(lower(d.DEV_NM||' '||d.MNG_NO),#{keyword})>0
    ORDER BY a.INPUT_BGN_DT ASC,a.ASGN_ID ASC

mapper.update:
UPDATE TB_PJ_ASGN SET INPUT_END_DT=#{row.endDate},CTRT_MM=#{row.monthlyMm},BILL_UPRC=#{row.billingPrice},
    INPUT_TYPE_CD=#{row.inputTypeCode},EXT_PSBL_CD=#{row.extensionPossibilityCode},EXT_CNT=#{row.extensionCount},EARLY_WTHDR_YN=#{row.earlyYn},ASGN_STAT_CD=#{row.statusCode},MOD_USER_ID=#{actor},MOD_DTTM=clock_timestamp()
    WHERE ASGN_ID=#{row.assignmentId} AND COALESCE(MOD_DTTM,REG_DTTM) IS NOT DISTINCT FROM #{token,jdbcType=TIMESTAMP_WITH_TIMEZONE}
